#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>

typedef struct Block { struct Block *next; } Block;

typedef struct {
    Block  *free_list;
    void   *slab;
    size_t  block_size, capacity, used;
} Pool;

static Pool *pool_create(size_t block_size, size_t capacity) {
    size_t bsz = (block_size + sizeof(void *) - 1) / sizeof(void *) * sizeof(void *);
    if (bsz < sizeof(Block)) bsz = sizeof(Block);

    Pool *p = malloc(sizeof(Pool));
    if (!p) return NULL;
    p->block_size = bsz;
    p->capacity   = capacity;
    p->used       = 0;
    p->slab       = malloc(bsz * capacity);      /* 只调用一次 malloc */
    if (!p->slab) { free(p); return NULL; }

    p->free_list = NULL;                          /* 串成空闲链表 */
    char *base = p->slab;
    for (size_t i = capacity; i-- > 0; ) {
        Block *b = (Block *)(base + i * bsz);
        b->next = p->free_list;
        p->free_list = b;
    }
    return p;
}

static void *pool_alloc(Pool *p) {
    if (!p || !p->free_list) return NULL;
    Block *b = p->free_list;
    p->free_list = b->next;
    p->used++;
    return b;
}

static void pool_free(Pool *p, void *ptr) {
    if (!p || !ptr) return;
    Block *b = ptr;
    b->next = p->free_list;
    p->free_list = b;
    p->used--;
}

static void pool_destroy(Pool *p) {
    if (!p) return;
    free(p->slab);
    free(p);
}

int main(void) {
    Pool *p = pool_create(24, 4);
    if (!p) return 1;

    printf("块大小(对齐后) = %zu\n", p->block_size);
    void *a = pool_alloc(p);
    void *b = pool_alloc(p);
    void *c = pool_alloc(p);
    void *d = pool_alloc(p);
    printf("分配 4 块后 used = %zu\n", p->used);
    printf("第 5 次分配 -> %s\n", pool_alloc(p) ? "成功(意外)" : "NULL(池已满)");

    pool_free(p, b);
    pool_free(p, d);
    printf("释放 2 块后 used = %zu\n", p->used);

    void *e = pool_alloc(p);          /* 复用刚释放的槽位 */
    printf("再分配 1 块后 used = %zu\n", p->used);
    printf("复用到的地址是否为已归还块 = %s\n",
           (e == b || e == d) ? "是" : "否");

    pool_free(p, a); pool_free(p, c); pool_free(p, e);
    printf("全部归还后 used = %zu\n", p->used);
    pool_destroy(p);
    return 0;
}
